package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Frequency_getCumPct_TriageGen0Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetCumPct_SumFreqZero_ReturnsNaN() {
        Frequency frequency = new Frequency();
        // sumFreq is 0, should return Double.NaN
        double result = frequency.getCumPct("anyValue");
        assertTrue("Expected NaN when sumFreq is 0", Double.isNaN(result));
    }

    @Test
    public void testGetCumPct_SingleValue_ReturnsOne() {
        Frequency frequency = new Frequency();
        frequency.addValue("A");

        // sumFreq = 1, getCumFreq("A") = 1 -> 1/1 = 1.0
        double result = frequency.getCumPct("A");
        assertEquals(1.0, result, DELTA);
    }

    @Test
    public void testGetCumPct_MultipleValues_ReturnsCorrectPercentage() {
        Frequency frequency = new Frequency();
        // Adding values to establish a sorted order for cumulative frequency
        // Assuming default comparator for Strings/Objects uses natural order
        frequency.addValue("A"); // Count 1
        frequency.addValue("B"); // Count 2
        frequency.addValue("B"); // Count 4 (total)
        frequency.addValue("C"); // Count 5 (total)

        // sumFreq = 5
        // getCumFreq("A") = 1 -> 1/5 = 0.2
        assertEquals(0.2, frequency.getCumPct("A"), DELTA);

        // getCumFreq("B") = 3 -> 3/5 = 0.6
        assertEquals(0.6, frequency.getCumPct("B"), DELTA);

        // getCumFreq("C") = 5 -> 5/5 = 1.0
        assertEquals(1.0, frequency.getCumPct("C"), DELTA);
    }

    @Test
    public void testGetCumPct_ValueNotInFrequency_ReturnsCumulativeUpToPreceding() {
        Frequency frequency = new Frequency();
        frequency.addValue(10);
        frequency.addValue(20);
        frequency.addValue(30);

        // sumFreq = 3
        // getCumFreq(15) should return count of values <= 15, which is 1 (the value 10)
        // 1/3 = 0.333...
        assertEquals(1.0 / 3.0, frequency.getCumPct(15), DELTA);

        // getCumFreq(5) should return 0
        assertEquals(0.0, frequency.getCumPct(5), DELTA);

        // getCumFreq(40) should return 3/3 = 1.0
        assertEquals(1.0, frequency.getCumPct(40), DELTA);
    }

    @Test
    public void testGetCumPct_WithIntegerTypes() {
        Frequency frequency = new Frequency();
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.addValue(3);

        // sumFreq = 3
        // getCumFreq(2) = 2 -> 2/3
        assertEquals(2.0 / 3.0, frequency.getCumPct(2), DELTA);
    }

    @Test
    public void testGetCumPct_AfterClear() {
        Frequency frequency = new Frequency();
        frequency.addValue("A");
        frequency.clear();

        // sumFreq is now 0
        assertTrue(Double.isNaN(frequency.getCumPct("A")));
    }
}
